import type { StorageHealth, StorageObject, StorageProvider, WriteOptions } from './types';

/**
 * Holds files in process memory. Used when permanent storage is off so a user can
 * still attach a file to the current conversation; nothing survives a process restart.
 */
export class MemoryStorageProvider implements StorageProvider {
	readonly backend = 'memory' as const;

	private readonly objects = new Map<string, { data: Buffer; contentType?: string; lastModified: Date }>();

	async write(key: string, data: Buffer, options?: WriteOptions): Promise<StorageObject> {
		const entry = {
			data: Buffer.from(data),
			contentType: options?.contentType,
			lastModified: new Date(),
		};
		this.objects.set(key, entry);
		return { key, size: entry.data.byteLength, contentType: entry.contentType, lastModified: entry.lastModified };
	}

	async read(key: string): Promise<Buffer> {
		const entry = this.objects.get(key);
		if (!entry) {
			const error = new Error(`ENOENT: no such file '${key}'`) as NodeJS.ErrnoException;
			error.code = 'ENOENT';
			throw error;
		}
		return Buffer.from(entry.data);
	}

	async list(prefix: string): Promise<StorageObject[]> {
		const listPrefix = prefix === '' || prefix.endsWith('/') ? prefix : `${prefix}/`;

		return [...this.objects.entries()]
			.filter(([key]) => (listPrefix === '' ? true : key.startsWith(listPrefix)))
			.map(([key, entry]) => ({
				key,
				size: entry.data.byteLength,
				contentType: entry.contentType,
				lastModified: entry.lastModified,
			}))
			.sort((a, b) => a.key.localeCompare(b.key));
	}

	async stat(key: string): Promise<StorageObject | null> {
		const entry = this.objects.get(key);
		if (!entry) {
			return null;
		}
		return {
			key,
			size: entry.data.byteLength,
			contentType: entry.contentType,
			lastModified: entry.lastModified,
		};
	}

	async exists(key: string): Promise<boolean> {
		return this.objects.has(key);
	}

	async delete(key: string): Promise<void> {
		this.objects.delete(key);
	}

	async healthCheck(): Promise<StorageHealth> {
		return { ok: true };
	}
}

